use std::collections::HashMap;

pub fn solve(input: &str) -> Option<HashMap<char, u8>> {
    let mut parts = input.split(" == ");
    let left = parts.next()?;
    let right = parts.next()?;
    // right is the result
    let result_word: Vec<char> = right.chars().filter(|c| c.is_ascii_alphabetic()).collect();
    let addends: Vec<Vec<char>> = left
        .split_whitespace()
        .filter(|w| w != "+")
        .map(|w| w.chars().filter(|c| c.is_ascii_alphabetic()).collect())
        .collect();

    let letters: Vec<char> = {
        let mut set = std::collections::HashSet::new();
        for word in &addends {
            for &c in word {
                set.insert(c);
            }
        }
        for &c in &result_word {
            set.insert(c);
        }
        let mut v: Vec<char> = set.into_iter().collect();
        v.sort();
        v
    };

    if letters.len() > 10 {
        return None;
    }

    // leading letters
    let mut leading = std::collections::HashSet::new();
    for word in &addends {
        if word.len() > 1 {
            leading.insert(word[0]);
        }
    }
    if result_word.len() > 1 {
        leading.insert(result_word[0]);
    }

    // Per-column coefficients: for each column, the list of (letter index, count)
