    // Column i from the right: addend word w contributes to column i if w.len() - 1 - i >= 0.
    let max_len = addends.iter().map(|w| w.len()).max().unwrap_or(0).max(result_word.len());

    // Build per column: addend coefficients as Vec<Vec<(usize, u8)>> (letter index -> count), and the result letter index.
