use std::collections::HashMap;
use std::collections::HashSet;

pub fn solve(input: &str) -> Option<HashMap<char, u8>> {
    let (lhs, rhs) = input.split_once("==")?;
    let addends: Vec<Vec<char>> = lhs
        .split_whitespace()
        .filter(|t| *t != "+")
        .map(|w| w.chars().collect())
        .collect();
    let result: Vec<char> = rhs.trim().chars().collect();

    let letters: Vec<char> = {
        let mut set: HashSet<char> = HashSet::new();
        for word in addends.iter().chain(std::iter::once(&result)) {
            for &c in word {
                set.insert(c);
            }
        }
        let mut v: Vec<char> = set.into_iter().collect();
        v.sort();
        v
    };

    if letters.len() > 10 {
        return None;
    }

    let idx: HashMap<char, usize> = letters.iter().enumerate().map(|(i, c)| (c, i)).collect();

    let mut leading: HashSet<usize> = HashSet::new();
    for word in addends.iter().chain(std::iter::once(&result)) {
        if word.len() > 1 {
            leading.insert(idx[&word[0]]);
        }
    }

    let max_len = addends.iter().map(|w| w.len()).max().unwrap_or(0).max(result.len());

    // Column coefficients: for column i (from the right), the letter counts among the addends.
    let mut columns: Vec<Vec<(usize, u16)>> = (0..max_len).map(|_| Vec::new()).collect();
    for word in &addends {
        for (i, &c) in word.iter().rev().enumerate() {
            let col = &mut columns[i];
            match col.iter_mut().find(|(l, _)| *l == idx[&c]) {
                Some(entry) => entry.1 += 1,
                None => col.push((idx[&c], 1)),
            }
        }
    }

    // Result letter at column i
    let result_cols: Vec<Option<usize>> = (0..max_len)
        .map(|i| {
            let pos = result.len() - 1 - i;
            (pos < result.len()).then(|| idx[&result[pos]])
        })
        .collect();

    let mut assignment = vec![None; letters.len()];
    let mut used = [false; 10];

    // Column index 0 is the rightmost.
    let solution = search(0, 0, &letters, &mut assignment, &mut used, &columns, &result_cols, &leading);
    solution.map(|a| {
        letters.iter().zip(a).map(|(c, d)| (c, d)).collect()
    })
}

