    carry: i64,
    letters: &[char],
    assignment: &mut [Option<u8>],
    used: &mut [bool; 10],
    columns: &[Vec<(usize, u16)>],
    result_cols: &[Option<usize>],
    leading: &HashSet<usize>,
) -> Option<Vec<u8>> {
